public void removeFromTreeEdgeList() {
    // Check if the current edge has a previous and next edge
    if (previous != null && next != null) {
        // Update the previous edge to point to the next edge
        previous.next = next;
        // Update the next edge to point to the previous edge
        next.previous = previous;
    } else if (previous == null && next != null) {
        // If there is no previous edge, but a next edge, set the head of the list to the next edge
        head = next;
        // Update the next edge to point to the previous edge (null)
        next.previous = null;
    } else if (previous != null && next == null) {
        // If there is no next edge, but a previous edge, set the tail of the list to the previous edge
        tail = previous;
        // Update the previous edge to point to the next edge (null)
        previous.next = null;
    } else {
        // If there are no edges in the list, set the head and tail to null
        head = null;
        tail = null;
    }
}

String findAndSubst(String key, Properties props) {
    // Step 1: Get the value for the given key from the props
    String value = props.getProperty(key);

    // Step 2: Perform variable substitution on the value if necessary
    if (value != null) {
        value = substituteVariables(value, props);
    }

    return value;
}

String substituteVariables(String value, Properties props) {
    // Step 1: Find all variables in the value
    Pattern variablePattern = Pattern.compile("\\$\\{([a-zA-Z_][a-zA-Z0-9_]*)\\}");
    Matcher variableMatcher = variablePattern.matcher(value);

    // Step 2: Replace each variable with its corresponding value from props
    StringBuffer substitutedValue = new StringBuffer();
    while (variableMatcher.find()) {
        String variable = variableMatcher.group(1);
        String replacement = props.getProperty(variable);
        variableMatcher.appendReplacement(substitutedValue, replacement != null ? replacement : "");
    }
    variableMatcher.appendTail(substitutedValue);

    return substitutedValue.toString();
}

