private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.edges()){
        List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = computeMinimalSeparatorList(e);
        globalSeparatorList.addAll(separatorList);
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeMinimalSeparatorList(E e){
    List<Pair<List<Pair<Integer,Integer>>,E>> minimalSeparatorList = new ArrayList<>();
    List<Pair<Integer,Integer>> neighborVertices = graph.getNeighborVertices(e);
    for (Pair<Integer,Integer> neighborVertex : neighborVertices){
        List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = computeMinimalSeparatorList(neighborVertex.second);
        for (Pair<List<Pair<Integer,Integer>>,E> separator : separatorList){
            minimalSeparatorList.add(new Pair<>(neighborVertex.first, separator.second));
        }
    }
    return minimalSeparatorList;
}

