    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        return new ArrayList<>();
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            long startTime = 0L;
            long endTime = 0L;
            String threadName = "";
            boolean isMainThread = false;

            // parse the line to extract the thread information
            String[] tokens = line.split(",");
            if (tokens.length >= 11) {
                startTime = Long.parseLong(tokens[0]);
                endTime = Long.parseLong(tokens[1]);
                threadName = tokens[2];
                isMainThread = Boolean.parseBoolean(tokens[3]);
            }

            // check if the thread snapshot falls within the time range
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (startTime >= timeRange.getStartTime() && endTime <= timeRange.getEndTime()) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) {
                continue;
            }

            // create a new thread snapshot
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, startTime, endTime, isMainThread);
            threadSnapshots.add(threadSnapshot);
        }
    }

    return threadSnapshots;
}
